package com.hokeka.edge.sanctions;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Matcher parity with aml-microservice: the vectors in
 * {@code docs/contracts/parity/sanctions-matcher-vectors.json} were generated by the aml-microservice
 * {@code SanctionsService} and are asserted there too ({@code SanctionsMatcherParityVectorsTest} in
 * aml-microservice). Here the Edge port and the in-memory index must reproduce every value exactly:
 * normalisation, pair scores (no tolerance) and full screening results (entries, scores, matched
 * names, order, top 5).
 */
class SanctionsMatcherParityVectorsTest {

    private static final Path VECTORS = Path.of(System.getProperty("contracts.dir", "../docs/contracts"),
            "parity", "sanctions-matcher-vectors.json");

    /** The shared vectors. */
    private static JsonNode vectors() throws Exception {
        assertTrue(Files.isRegularFile(VECTORS), "parity vectors not found at " + VECTORS.toAbsolutePath());
        return new ObjectMapper().readTree(Files.readString(VECTORS));
    }

    @Test
    void normalisationMatchesAmlMicroservice() throws Exception {
        for (JsonNode v : vectors().get("normalize")) {
            assertEquals(v.get("normalized").asText(), SanctionsMatcher.normalize(v.get("input").asText()),
                    "normalize(" + v.get("input").asText() + ")");
        }
    }

    @Test
    void pairScoresMatchAmlMicroserviceExactly() throws Exception {
        JsonNode pairs = vectors().get("pairs");
        assertTrue(pairs.size() > 100);
        for (JsonNode p : pairs) {
            double actual = SanctionsMatcher.similarity(SanctionsMatcher.normalize(p.get("a").asText()),
                    SanctionsMatcher.normalize(p.get("b").asText()));
            assertEquals(p.get("score").asDouble(), actual, 0.0, p.get("a").asText() + " vs " + p.get("b").asText());
        }
    }

    @Test
    void indexedScreeningMatchesAmlMicroserviceScreening() throws Exception {
        JsonNode root = vectors();
        List<SanctionsEntry> entries = new ArrayList<>();
        for (JsonNode e : root.get("entries")) {
            List<String> aliases = new ArrayList<>();
            e.get("aliases").forEach(a -> aliases.add(a.asText()));
            entries.add(new SanctionsEntry(e.get("id").asText(), e.get("name").asText(), aliases,
                    e.get("type").asText(), e.has("pepLevel") ? e.get("pepLevel").asText() : null));
        }
        SanctionsIndex index = new SanctionsIndex(entries, root.get("similarityThreshold").asDouble());
        assertEquals(root.get("topN").asInt(), SanctionsIndex.TOP_N);
        for (JsonNode screen : root.get("screens")) {
            String query = screen.get("query").asText();
            List<SanctionsIndex.Match> actual = index.screen(query);
            JsonNode expected = screen.get("matches");
            assertEquals(expected.size(), actual.size(), "match count for '" + query + "'");
            for (int i = 0; i < actual.size(); i++) {
                assertEquals(expected.get(i).get("entryId").asText(), actual.get(i).entry().id(), query);
                assertEquals(expected.get(i).get("score").asDouble(), actual.get(i).score(), 0.0, query);
                assertEquals(expected.get(i).get("matched").asText(), actual.get(i).matched(), query);
            }
            assertEquals(index.screenByFullScan(query), actual, "index and full scan agree for '" + query + "'");
        }
    }
}
